"""#564: the ZMod .gcode.3mf package, its header metadata, and format resolution."""
import hashlib
import json
import zipfile
from pathlib import Path

import pytest

from print_handy import firmware_update, settings
from print_handy.core import gcode_3mf

GCODE = """; HEADER_BLOCK_START
; generated by OrcaSlicer 2.5.0-alpha
; HEADER_BLOCK_END
; filament_type = PLA;PETG
; filament_colour = #FF0000;#00FF00
; filament used [g] = 10.5;2.25
; estimated printing time (normal mode) = 1h 2m 3s
; nozzle_diameter = 0.4
; MD5:0123456789abcdef0123456789abcdef
M190 S60
M104 S210 T0
START_PRINT BED_TEMP=60 EXTRUDER_TEMP=210 MESH=auto
G1 X10 Y10 Z0.2 E1
END_PRINT
"""


def _gcode(tmp_path, text=GCODE):
    path = tmp_path / "plate_1.gcode"
    path.write_text(text)
    return path


def test_package_holds_the_gcode_byte_identical_with_its_metadata(tmp_path):
    gcode = _gcode(tmp_path)
    target = gcode_3mf.package(gcode, tmp_path / "plate_1.gcode.3mf", nozzle_mm=0.4)
    with zipfile.ZipFile(target) as archive:
        names = archive.namelist()
        assert "[Content_Types].xml" in names and "_rels/.rels" in names
        assert "3D/3dmodel.model" in names
        inner = archive.read("Metadata/plate_1.gcode")
        assert inner == gcode.read_bytes()
        sidecar = archive.read("Metadata/plate_1.gcode.md5").decode()
        assert sidecar == hashlib.md5(inner).hexdigest().upper()
        plate = json.loads(archive.read("Metadata/plate_1.json"))
        assert archive.read("Metadata/slice_info.config").decode().count('key="index"') == 1
    assert plate["index"] == 1
    assert plate["filaments"] == [
        {"id": 1, "type": "PLA", "color": "#FF0000", "used_g": 10.5},
        {"id": 2, "type": "PETG", "color": "#00FF00", "used_g": 2.25},
    ]
    assert plate["prediction"] == 3723
    assert plate["weight"] == 12.75


def test_package_is_deterministic(tmp_path):
    gcode = _gcode(tmp_path)
    first = gcode_3mf.package(gcode, tmp_path / "a.gcode.3mf").read_bytes()
    second = gcode_3mf.package(gcode, tmp_path / "b.gcode.3mf").read_bytes()
    assert first == second


def test_package_carries_thumbnails_when_given(tmp_path):
    gcode = _gcode(tmp_path)
    target = gcode_3mf.package(gcode, tmp_path / "p.gcode.3mf",
                               thumbnails={"plate": b"PNG512", "plate_small": b"PNG128"})
    with zipfile.ZipFile(target) as archive:
        assert archive.read("Metadata/plate_1.png") == b"PNG512"
        assert archive.read("Metadata/plate_1_small.png") == b"PNG128"


def test_read_gcode_text_plain_and_packaged(tmp_path):
    gcode = _gcode(tmp_path)
    assert gcode_3mf.read_gcode_text(gcode) == GCODE
    target = gcode_3mf.package(gcode, tmp_path / "plate_1.gcode.3mf")
    assert gcode_3mf.read_gcode_text(target) == GCODE
    assert gcode_3mf.is_package(target) and not gcode_3mf.is_package(gcode)
    assert gcode_3mf.package_path_for(gcode) == tmp_path / "plate_1.gcode.3mf"


def test_read_gcode_text_refuses_ambiguous_or_empty_packages(tmp_path):
    two = tmp_path / "two.gcode.3mf"
    with zipfile.ZipFile(two, "w") as archive:
        archive.writestr("Metadata/plate_1.gcode", "G28\n")
        archive.writestr("Metadata/plate_2.gcode", "G28\n")
    with pytest.raises(RuntimeError, match="single-plate"):
        gcode_3mf.read_gcode_text(two)
    empty = tmp_path / "empty.gcode.3mf"
    with zipfile.ZipFile(empty, "w") as archive:
        archive.writestr("3D/3dmodel.model", "<model/>")
    with pytest.raises(RuntimeError, match="single-plate"):
        gcode_3mf.read_gcode_text(empty)


def test_plate_metadata_omits_what_the_header_does_not_carry():
    meta = gcode_3mf.plate_metadata("G28\nG1 X1\n")
    assert meta == {"index": 1, "filaments": []}
    meta = gcode_3mf.plate_metadata("; filament_type = PLA\n", plate=1)
    assert meta["filaments"] == [{"id": 1, "type": "PLA"}]
    assert "prediction" not in meta and "weight" not in meta


@pytest.mark.parametrize("setting,version,want", [
    ("gcode", (1, 7, 5), "gcode"),
    ("gcode", None, "gcode"),
    ("3mf", (1, 6, 0), "3mf"),          # operator override wins over the floor
    ("3mf", None, "3mf"),
    ("auto", (1, 7, 5), "3mf"),         # the floor itself
    ("auto", (1, 7, 6), "3mf"),
    ("auto", (2, 0), "3mf"),
    ("auto", (1, 7, 4), "gcode"),       # one release too old
    ("auto", (1, 6, 6), "gcode"),
    ("auto", None, "gcode"),            # unknown is today's behaviour
    ("bogus", (1, 7, 5), "gcode"),      # an unreadable value never selects the new format
])
def test_resolve_format(setting, version, want):
    got, reason = gcode_3mf.resolve_format(setting, version)
    assert got == want and reason


def _status(*components):
    return firmware_update.UpdateStatus(components=tuple(
        firmware_update.Component(name=name, current=current) for name, current in components))


@pytest.mark.parametrize("status,want", [
    (_status(("zmod", "1.7.5")), (1, 7, 5)),
    (_status(("zmod", "v1.7.10")), (1, 7, 10)),
    (_status(("ZMOD", "1.8")), (1, 8)),
    (_status(("klipper", "1.0")), None),          # no zmod component reported
    (_status(("zmod", None)), None),              # component without a current version
    (_status(("zmod", "unknown")), None),         # unparseable version
    (None, None),
])
def test_version_from_status(status, want):
    assert gcode_3mf.version_from_status(status) == want


def _load(environ):
    return settings.load(home=settings.HOME, local=False, environ=environ)


def test_setting_defaults_to_auto_for_zmod_and_is_absent_elsewhere():
    assert _load({})["printer"]["zmod_delivery_format"] == "auto"
    klipper = _load({"PRINT_HANDY__PRINTER__MODEL": "klipper.generic"})
    assert "zmod_delivery_format" not in klipper["printer"]


def test_setting_accepts_each_value_for_zmod():
    for value in ("gcode", "3mf", "auto"):
        data = _load({"PRINT_HANDY__PRINTER__ZMOD_DELIVERY_FORMAT": value})
        assert data["printer"]["zmod_delivery_format"] == value


def test_setting_refuses_bad_values_and_other_vendors():
    with pytest.raises(settings.SettingsError, match="zmod_delivery_format"):
        _load({"PRINT_HANDY__PRINTER__ZMOD_DELIVERY_FORMAT": "zip"})
    with pytest.raises(settings.SettingsError, match="only applies to Flashforge"):
        _load({"PRINT_HANDY__PRINTER__MODEL": "klipper.generic",
               "PRINT_HANDY__PRINTER__ZMOD_DELIVERY_FORMAT": "3mf"})
